entries[32837] = { ["name"] = "Kriegsgleve von Azzinoth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Schwert\n214 - 398 Schaden Tempo 2.80\n(109.29 Schaden pro Sekunde)\n+22 Beweglichkeit\n+47 Ausdauer\nHaltbarkeit 130 / 130\nKlassen: Krieger , Schurke , Todesritter\nBenötigt Stufe 70\nAnlegen: Erhöht die Trefferwertung um 21.\n\nDie Zwillingsklingen von Azzinoth (0/2)\nKriegsgleve von Azzinoth\nKriegsgleve von Azzinoth\n(2) Set : Eure Nahkampfangriffe haben die Chance, Eure Tempowertung 10 Sek. lang um 450 zu erhöhen. (45s Abklingzeit)\n(2) Set : Erhöht Angriffskraft im Kampf gegen Dämonen um 200.\nVerkaufspreis:" }
entries[32838] = { ["name"] = "Kriegsgleve von Azzinoth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchildhand Schwert\n107 - 199 Schaden Tempo 1.40\n(109.29 Schaden pro Sekunde)\n+21 Beweglichkeit\n+46 Ausdauer\nHaltbarkeit 130 / 130\nKlassen: Krieger , Schurke , Todesritter\nBenötigt Stufe 70\nAnlegen: Erhöht die kritische Trefferwertung um 23.\n\nDie Zwillingsklingen von Azzinoth (0/2)\nKriegsgleve von Azzinoth\nKriegsgleve von Azzinoth\n(2) Set : Eure Nahkampfangriffe haben die Chance, Eure Tempowertung 10 Sek. lang um 450 zu erhöhen. (45s Abklingzeit)\n(2) Set : Erhöht Angriffskraft im Kampf gegen Dämonen um 200.\nVerkaufspreis:" }
entries[32839] = { ["name"] = "Kessel des erheblichen Arkanschutzes", ["text"] = "Benötigt Stufe 60\nBenutzen: Stellt einen Kessel her, der von anderen Schlachtzugsmitgliedern benutzt werden kann, um einen erheblichen Arkanschutztrank herbeizuzaubern. Der Kessel enthält 25 Anwendungen und bleibt 5 Min. lang bestehen.\n\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Minuten ausloggt.\nVerkaufspreis:" }
