entries[32897] = { ["name"] = "Mal der Illidari", ["text"] = "\"Trägt das Mal der Illidari. Dieser Gegenstand kann bei der Bank der Seher oder der Aldor in Shattrath eingetauscht werden.\"" }
entries[32898] = { ["name"] = "Fläschchen der Stärkung aus Shattrath", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 70\nBenutzen: Erhöht 1 Stunde lang die maximale Gesundheit um 500 und die Ausweichwertung um 10. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau. (3 Sek. Abklingzeit)" }
entries[32899] = { ["name"] = "Fläschchen der mächtigen Wiederherstellung aus Shattrath", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 70\nBenutzen: Erhöht die Willenskraft 1 Stunde lang um 62. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau. (3 Sek. Abklingzeit)" }
entries[32900] = { ["name"] = "Fläschchen der obersten Macht aus Shattrath", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 70\nBenutzen: Erhöht die Schadenswirkung von Zaubern und magischen Effekten 1 Stunde lang um bis zu 70. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau. (3 Sek. Abklingzeit)" }
entries[32901] = { ["name"] = "Fläschchen des unerbittlichen Angriffs aus Shattrath", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 70\nBenutzen: Erhöht die Angriffskraft 1 Stunde lang um 120. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Dieser Effekt hält über den Tod hinaus an.\n\nWirkt nur in der Festung der Stürme, der Höhle des Schlangenschreins, den Höhlen der Zeit: Berg Hyjal, dem Schwarzen Tempel und dem Sonnenbrunnenplateau. (3 Sek. Abklingzeit)" }
entries[32902] = { ["name"] = "Flasche mit Nethergonenergie", ["text"] = "Benötigt Stufe 55\nBenutzen: Stellt 1800 to 3000 Mana wieder her.\n\nWirkt nur in der Festung der Stürme: das Auge, die Arkatraz, die Botanika, die Mechanar. (1 Min Abklingzeit)\n\"In den nächstgelegenen Energieanschluss einspeisen.\"" }
