entries[32905] = { ["name"] = "Flasche mit Nethergondampf", ["text"] = "Benötigt Stufe 55\nBenutzen: Stellt 1500 to 2500 Gesundheit wieder her.\n\nWirkt nur in der Festung der Stürme: das Auge, die Arkatraz, die Botanika, die Mechanar. (1 Min Abklingzeit)\n\"Tief einatmen.\"" }
entries[32906] = { ["name"] = "Betäubter Wolpertinger", ["text"] = "Questgegenstand\nEinzigartig (5)\nDauer: 30 min (Realzeit)\n\"Der Kleine scheint ein wenig neben der Kappe zu sein...\"" }
entries[32907] = { ["name"] = "Wolpertingernetz", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Wirft ein Netz auf einen wilden Wolpertinger, wodurch Ihr ihn einfangen und in Eurem Rucksack verstauen könnt. (5 Sek. Abklingzeit)\n12 Aufladungen" }
