entries[33088] = { ["name"] = "Broggs Totem", ["text"] = "Questgegenstand\nBenutzen: Entfesselt die Magie von Broggs Totem über dem Leichnam eines Aschenschweifs der Feuermähnen, Spähers der Feuermähnen oder einer Bannschuppe der Feuermähnen." }
entries[33091] = { ["name"] = "Energiegeladenes Totem", ["text"] = "Questgegenstand\nBenutzen: Bettet die Überreste eines Ogers in den Ruinen der Steinbrecher zur Ruhe.\n\"Broggs fertiges Totem.\"" }
