entries[33096] = { ["name"] = "Freibierkrug des Braufests", ["text"] = "Herbeigezauberter Gegenstand\nEinzigartig\nBenötigt Braufest\nBenutzen: Trinkt das Gebräu und werft den Krug!\n\"Freibier in einem spaßigen Krug zum Werfen!\"" }
entries[33097] = { ["name"] = "Pilzring", ["text"] = "Wird beim Anlegen gebunden\nFinger\n+15 Ausdauer\nBenötigt Stufe 66\n\"Dieser schwammartige Ring ist erstaunlich widerstandsfähig.\"\nVerkaufspreis:" }
entries[33098] = { ["name"] = "Petrovs Splitterbomben", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Auf die belagernden Piraten werfen, um diese zu töten. Kann nur geworfen werden, während Ihr Euch an Bord des Zeppelins befindet.\n\"Neu! Jetzt mit der Kraft von Fledermausguano!\"" }
entries[33099] = { ["name"] = "Unversehrter Seuchenbehälter", ["text"] = "Questgegenstand\n\"Ein Etikett warnt davor, dieses Fläschchen ohne Schutz zu hantieren.\"" }
entries[33100] = { ["name"] = "Lysanders Brandbombe", ["text"] = "Questgegenstand" }
