entries[33805] = { ["name"] = "Schattenjägertreter", ["text"] = "Wird beim Aufheben gebunden\nFüße Kette\n696 Rüstung\n+33 Beweglichkeit\n+48 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 70\nAnlegen: Erhöht die kritische Trefferwertung um 15.\nAnlegen: Erhöht die Tempowertung um 26.\nVerkaufspreis:" }
