entries[33807] = { ["name"] = "Vazrudens Horn", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein bisschen zu kunstvoll für einen Höllenorc. Wahrscheinlich war es ein Geschenk seines Meisters.\"" }
