entries[33814] = { ["name"] = "Keli'dans gefiederter Stab", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Federn sehen vom Kampf ein wenig mitgenommen aus, aber sind dennoch in einem guten Zustand.\"" }
entries[33815] = { ["name"] = "Messerfausts Siegel", ["text"] = "Questgegenstand\nEinzigartig\n\"Aus den härtesten Metallen geschmiedet, trägt es das Siegel des verstorbenen Kriegshäuptlings.\"" }
entries[33816] = { ["name"] = "Zähnchens Eimer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Babykrokilisk Zähnchen beschwören oder wieder freigeben." }
entries[33818] = { ["name"] = "Matschbrabbels Eimer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Babykrokilisk Matschbrabbel beschwören oder wieder freigeben." }
entries[33819] = { ["name"] = "Probestück einer Rune", ["text"] = "Questgegenstand\nBenutzen: Vergleicht die Runen des Probestücks mit denen auf der zerbrochenen Schrifttafel. (1 Min Abklingzeit)\n\"Ein kleiner, runenbesetzter Brocken, der aus einem Steinriesen herausgehauen wurde.\"" }
entries[33820] = { ["name"] = "Wettergegerbter Angelhut", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n31 Rüstung\n+3 Ausdauer\n+3 Willenskraft\nHaltbarkeit 50 / 50\nAnlegen: Fertigkeit im Angeln um 5 erhöht.\nBenutzen: Bringt einen Köder an Eurer Angelrute an, der 10 Min. lang Eure Fähigkeit 'Angeln' um 75 erhöht. (10 Min Abklingzeit)\nVerkaufspreis:" }
entries[33821] = { ["name"] = "Das Herz von Quagmirran", ["text"] = "Questgegenstand\nEinzigartig\n\"Eines von drei Herzen. Es sieht ein wenig wie eine Artischocke aus.\"" }
