entries[33827] = { ["name"] = "Die Aufzeichnungen des Kriegsherren", ["text"] = "Questgegenstand\nEinzigartig\n\"Mit der wasserfesten Tinte der Naga geschrieben, umfasst dieses Buch mehr als tausend Seiten.\"" }
