entries[33833] = { ["name"] = "Nazans Reitgerte", ["text"] = "Questgegenstand\nEinzigartig\n\"Damit kann man sicherlich viel Schmerz verursachen.\"" }
entries[33834] = { ["name"] = "Die Kopfschmuckfedern von Ikiss", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Federn sind in wunderschönen Herbsttönen gehalten.\"" }
entries[33835] = { ["name"] = "Shaffars wundersames Amulett", ["text"] = "Questgegenstand\nEinzigartig\n\"Dies ist die Quelle von Nexusprinz Shaffars Magie. Zu schade, dass Ihr nicht wisst, wie man es benutzt.\"" }
entries[33836] = { ["name"] = "Der Seelenedelstein des Exarchen", ["text"] = "Questgegenstand\nEinzigartig\n\"Es ist kaum zu glauben, dass dieses Ding die Seelen vieler Opfer enthält. Dennoch spürt Ihr ihre Unruhe ganz deutlich.\"" }
entries[33837] = { ["name"] = "Kochtopf", ["text"] = "Questgegenstand\nBenötigt Kochkunst (275)\nBenutzen: Bereitet mit 3 Doppelwarpern und 1 riesigen Kaliriflügel Kalirieintopf zu." }
