entries[33851] = { ["name"] = "Kochtopf", ["text"] = "Questgegenstand\nBenötigt Kochkunst (275)\nBenutzen: Bereitet mit 4 gerösteten Grollhufen spirituelle Suppe zu.\n\"Kann nur beim Ahnengrund in Nagrand benutzt werden.\"" }
