entries[33854] = { ["name"] = "Unidentifizierbares Auge", ["text"] = "\"Möglicherweise gehörte es mal einem Tier, vielleicht aber auch nicht.\"\nVerkaufspreis:" }
entries[33855] = { ["name"] = "Angelaufener Silberring", ["text"] = "Finger\n\"Der Ring hat auch schon bessere Zeiten erlebt.\"\nVerkaufspreis:" }
